R=Path(a.root).resolve();S=Path(a.packet).resolve();W=Path(a.work).resolve();N=Path(a.node).resolve();B=Path(a.bwrap).resolve();prefix='curricula/quality/cross-subject-requires/2026-10-16/first20-current72-scientific-reconciliation-v1'
